var TC = (typeof globalThis.TC !== 'undefined') ? globalThis.TC : {};
// GENERATED by tools/embed.js from games/pong.asm -- do not edit.
TC.samples = TC.samples || {};
TC.samples.pong = `; ============================================================
; PONG for the TC-8
; Left paddle (white) is yours: KEY 1=up 2=down.
; Right paddle (red) is a simple AI: it moves one pixel per step
; toward the ball, and only while the ball is on its half, so it
; can miss. Ball (green) moves diagonally and bounces off the
; top/bottom walls and the paddles.
; AI misses: SCORE +1 and the ball is served again from the center.
; You miss: the screen flashes red, then the ball is served again.
; There is no end state: the rally goes on forever.
; ============================================================

; ---- memory-mapped I/O ----
.equ KEY,    0xF0        ; last key, clears on read
.equ RNG,    0xF1        ; next random byte (never 0)
.equ FRAME,  0xF2        ; +1 every 2000 instructions
.equ SCORE,  0xF3        ; shown by the UI

; ---- game data in RAM ----
.equ PY,     0x20        ; top row of the player's paddle (0..13)
.equ AY,     0x21        ; top row of the AI's paddle (0..13)
.equ BALLX,  0x22        ; ball x
.equ BALLY,  0x23        ; ball y
.equ DX,     0x24        ; ball x direction: 1 or 0xFF (-1)
.equ DY,     0x25        ; ball y direction: 1 or 0xFF (-1)
.equ DELAY,  0x26        ; frames left until the next step
.equ LASTF,  0x27        ; last FRAME value seen

; ---- tuning ----
.equ STEP_FRAMES, 4      ; frames per step (bigger = slower)
.equ FLASH_FRAMES, 12    ; how long the miss flash lasts
.equ LEFT_X,  0          ; paddle columns
.equ RIGHT_X, 15
.equ WHITE,  3
.equ RED,    2
.equ GREEN,  1

start:
        CALL init_game

; ------------------------------------------------------------
; Main loop: move your paddle on every key; step on the timer
; ------------------------------------------------------------
main:
        LDA  R0, [KEY]          ; reading KEY also clears it
        LDI  R4, 0xFF           ; R4 = delta: -1 (up)
        CMPI R0, 1
        JZ   do_move
        LDI  R4, 1              ; +1 (down)
        CMPI R0, 2
        JNZ  no_key
do_move:
        CALL move_player
no_key:
        LDA  R0, [FRAME]        ; wait until FRAME changes
        LDA  R1, [LASTF]
        CMP  R0, R1
        JZ   main
        STA  [LASTF], R0
        LDA  R0, [DELAY]        ; count down frames
        SUBI R0, 1
        STA  [DELAY], R0
        JNZ  main
        LDI  R0, STEP_FRAMES
        STA  [DELAY], R0
        CALL game_step
        JMP  main

; ------------------------------------------------------------
; init_game: paddles mid-field, score 0, serve
; ------------------------------------------------------------
init_game:
        CALL clear_screen
        LDI  R0, 0
        STA  [SCORE], R0
        LDI  R0, 6
        STA  [PY], R0
        STA  [AY], R0
        CALL draw_paddles
        LDI  R0, STEP_FRAMES
        STA  [DELAY], R0
        LDA  R0, [FRAME]
        STA  [LASTF], R0
        CALL serve
        RET

; ------------------------------------------------------------
; clear_screen: VRAM[0..255] = 0
; ------------------------------------------------------------
clear_screen:
        LDI  R0, 0
        LDI  R1, 0
cs_loop:
        VST  [R0], R1
        ADDI R0, 1
        JNC  cs_loop            ; carry when R0 wraps 255 -> 0
        RET

; ------------------------------------------------------------
; draw_paddle: 3 cells in column R1 from row R2 down, color R5
; (uses R3)
; ------------------------------------------------------------
draw_paddle:
        MOV  R3, R2
        SHL  R3                 ; R3 = top * 16 + x
        SHL  R3
        SHL  R3
        SHL  R3
        ADD  R3, R1
        VST  [R3], R5
        ADDI R3, 16
        VST  [R3], R5
        ADDI R3, 16
        VST  [R3], R5
        RET

draw_paddles:
        LDI  R1, LEFT_X
        LDA  R2, [PY]
        LDI  R5, WHITE
        CALL draw_paddle
        LDI  R1, RIGHT_X
        LDA  R2, [AY]
        LDI  R5, RED
        CALL draw_paddle
        RET

; ------------------------------------------------------------
; paint_ball: paint the ball's cell with color R5 (uses R1, R2)
; ------------------------------------------------------------
paint_ball:
        LDA  R2, [BALLY]
        SHL  R2
        SHL  R2
        SHL  R2
        SHL  R2
        LDA  R1, [BALLX]
        ADD  R2, R1
        VST  [R2], R5
        RET

; ------------------------------------------------------------
; serve: ball to the center, heading toward you, random up/down
; ------------------------------------------------------------
serve:
        LDI  R0, 7
        STA  [BALLX], R0
        STA  [BALLY], R0
        LDI  R0, 0xFF
        STA  [DX], R0           ; toward the player
        LDA  R0, [RNG]
        ANDI R0, 1              ; random bit picks the vertical direction
        LDI  R1, 1              ; (LDI leaves the flags alone)
        JNZ  sv_dy
        LDI  R1, 0xFF
sv_dy:
        STA  [DY], R1
        LDI  R5, GREEN
        CALL paint_ball
        RET

; ------------------------------------------------------------
; move_player: move your paddle by R4 (+1 / -1), kept on screen
; ------------------------------------------------------------
move_player:
        LDA  R2, [PY]
        MOV  R0, R2
        ADD  R0, R4             ; R0 = new top
        CMPI R0, 14             ; valid tops are 0..13 (-1 wraps to 255)
        JNC  mp_done
        LDI  R1, LEFT_X
        LDI  R5, 0
        CALL draw_paddle        ; erase at the old top (R2)
        STA  [PY], R0
        MOV  R2, R0
        LDI  R5, WHITE
        CALL draw_paddle
mp_done:
        RET

; ------------------------------------------------------------
; ai_move: once the ball is on the right half, move the red
; paddle one pixel toward the ball's row
; ------------------------------------------------------------
ai_move:
        LDA  R1, [BALLX]
        CMPI R1, 8
        JC   ai_done            ; ball on the left half: wait
        LDA  R2, [AY]
        LDA  R3, [BALLY]
        MOV  R4, R2
        ADDI R4, 1              ; R4 = paddle center row
        CMP  R3, R4
        JZ   ai_done            ; already lined up
        LDI  R0, 1              ; ball below center: move down
        JNC  ai_go
        LDI  R0, 0xFF           ; ball above center: move up
ai_go:
        MOV  R4, R2
        ADD  R4, R0             ; R4 = new top
        CMPI R4, 14
        JNC  ai_done            ; would leave the screen
        LDI  R1, RIGHT_X
        LDI  R5, 0
        CALL draw_paddle        ; erase at the old top (R2)
        STA  [AY], R4
        MOV  R2, R4
        LDI  R5, RED
        CALL draw_paddle
ai_done:
        RET

; ------------------------------------------------------------
; game_step: AI moves, then the ball moves one cell diagonally
; Registers: R1 ball x, R2 ball y, R4 new y, R5 new x
; ------------------------------------------------------------
game_step:
        CALL ai_move
        LDI  R5, 0
        CALL paint_ball         ; erase the ball
        LDA  R1, [BALLX]
        LDA  R2, [BALLY]
        ; --- vertical: bounce off the top and bottom walls ---
        LDA  R3, [DY]
        MOV  R4, R2
        ADD  R4, R3             ; R4 = new y
        CMPI R4, 16
        JC   gs_y_ok            ; 0..15: still on screen
        LDI  R0, 0
        SUB  R0, R3             ; flip: DY = -DY
        STA  [DY], R0
        MOV  R4, R2
        ADD  R4, R0
gs_y_ok:
        ; --- horizontal: what is in the cell we move into? ---
        LDA  R3, [DX]
        MOV  R5, R1
        ADD  R5, R3             ; R5 = new x
        MOV  R6, R4
        SHL  R6
        SHL  R6
        SHL  R6
        SHL  R6
        ADD  R6, R5
        VLD  R0, [R6]
        CMPI R0, 0
        JZ   gs_free
        ; a paddle is there: bounce back horizontally
        LDI  R0, 0
        SUB  R0, R3             ; DX = -DX
        STA  [DX], R0
        MOV  R5, R1
        ADD  R5, R0             ; move away from the paddle instead
        JMP  gs_move
gs_free:
        CMPI R5, LEFT_X
        JZ   player_miss        ; got past your paddle
        CMPI R5, RIGHT_X
        JZ   ai_miss            ; got past the AI's paddle
gs_move:
        STA  [BALLX], R5
        STA  [BALLY], R4
        LDI  R5, GREEN
        CALL paint_ball
        RET

; ------------------------------------------------------------
; ai_miss: you score, serve again
; ------------------------------------------------------------
ai_miss:
        LDA  R0, [SCORE]
        ADDI R0, 1
        STA  [SCORE], R0
        CALL serve
        RET

; ------------------------------------------------------------
; player_miss: flash the screen red, redraw, serve (no score)
; ------------------------------------------------------------
player_miss:
        LDI  R0, 0
        LDI  R1, RED
pm_fill:
        VST  [R0], R1
        ADDI R0, 1
        JNC  pm_fill
        LDI  R5, FLASH_FRAMES
        CALL wait_frames
        CALL clear_screen
        CALL draw_paddles
        CALL serve
        RET

; ------------------------------------------------------------
; wait_frames: wait for R5 FRAME changes (uses R3, R4, R5)
; ------------------------------------------------------------
wait_frames:
        LDA  R3, [FRAME]
wf_loop:
        LDA  R4, [FRAME]
        CMP  R3, R4
        JZ   wf_loop
        MOV  R3, R4
        SUBI R5, 1
        JNZ  wf_loop
        RET
`;
if (typeof module !== 'undefined') module.exports = globalThis.TC = TC; else globalThis.TC = TC;
